// Molten Boulder rolls a fixed line and shoves monsters rather than tracking a
// single target. The front corridor is bulldozed for the whole roll, flank
// touches are knocked aside once, and the rock bursts where the roll ends.
// D2 sends one rock down the line, so the cast never doubles up on the art.
const BOULDER_COUNT = 1;
const BOULDER_RADIUS = 24;
const BOULDER_SPEED = 300;
const BOULDER_MIN_RANGE = 380;
const BOULDER_MAX_RANGE = 760;
const BOULDER_LINE_SPREAD = 0.07;
const BOULDER_SIDE_KNOCKBACK = 56;
const BOULDER_EXPLOSION_RADIUS = 88;
const BOULDER_EXPLOSION_DURATION = 0.55;
// D2 missile cels are drawn toward isometric north-east, roughly 22.5 degrees
// above screen-right. Without this correction an arrow flies visibly sideways.
const ISOMETRIC_MISSILE_ROTATION = Math.PI / 8;
// The Fire Bolt and Fire Ball cels are authored flying toward the lower-left of
// the frame (bright head low-left, flame trailing up-right), which is 135
// degrees clockwise from screen-right. Without this correction the rotation
// below turns the cel with the shot but leaves the flame permanently pointing
// 135 degrees off its travel vector, so it looked like it never faced anywhere.
const FIRE_MISSILE_ROTATION = -3 * Math.PI / 4;
const MISSILE_SPRITE_ORIENTATIONS: Record<string, number> = {
  "d2-arrow": ISOMETRIC_MISSILE_ROTATION,
  "d2-xbowbolt": ISOMETRIC_MISSILE_ROTATION,
  "d2-javelin": ISOMETRIC_MISSILE_ROTATION,
  "d2-pilum": ISOMETRIC_MISSILE_ROTATION,
  "d2-safearrow": ISOMETRIC_MISSILE_ROTATION,
  "d2-firearrow": ISOMETRIC_MISSILE_ROTATION,
  "d2-icearrow": ISOMETRIC_MISSILE_ROTATION,
  "d2-lightningjavelin": ISOMETRIC_MISSILE_ROTATION,
  "d2-lightningstrike": ISOMETRIC_MISSILE_ROTATION,
  "d2-spikefiendmissle": ISOMETRIC_MISSILE_ROTATION,
  "d2-firebolt": FIRE_MISSILE_ROTATION,
  "d2-fireball": FIRE_MISSILE_ROTATION,
  "d2-glaive": ISOMETRIC_MISSILE_ROTATION,
  "d2-missileglaive": ISOMETRIC_MISSILE_ROTATION,
  "d2-missilehandaxe": ISOMETRIC_MISSILE_ROTATION,
  "d2-missileaxe": ISOMETRIC_MISSILE_ROTATION,
  "d2-missiledagger": ISOMETRIC_MISSILE_ROTATION,
  // Bolt and flame-column cels are authored pointing up the screen.
  "43": Math.PI / 2,
  "55": Math.PI / 2,
  "74": Math.PI / 2,
  "d2-inferno": Math.PI / 2,
  // The original DCC effects below are authored pointing up the screen, so the
  // sprite needs +90 degrees before it follows its travel vector.
  "d2-lightningbolt": Math.PI / 2,
  "d2-groundfirebig": Math.PI / 2,
  "d2-groundfiresmall": Math.PI / 2,
  "d2-flamethrower": Math.PI / 2,
  "d2-flamethrower2": Math.PI / 2,
  "d2-blizzard": Math.PI / 2,
  "d2-arcticblastice": Math.PI / 2,
  "d2-eruptionsmoke": Math.PI / 2,
  // The meteor cel's rock leads at the bottom, so its forward axis points down.
  "d2-meteortail": -Math.PI / 2,
  // SandMaggotGooSpit's main glob leads down-left while its spray trails
  // up-right. Turn the authored diagonal around so the glob leads the flight;
  // aligning the up-right spray with travel made the missile look reversed.
  "d2-sandmaggotgoospit": Math.PI * 5 / 4,
};
