interface CampaignArea {
  /** Area name as it appears in Diablo II's own area tables. */
  name: string;
  /** Normal-difficulty area level; drives both difficulty and tile changes. */
  level: number;
  /** 4x4 atlas of floor tiles for this area (160x80 or 320x160 cells). */
  floorTiles: string;
  /** Atlas cell whose terrain family anchors this zone's ground palette. */
  baseFloorVariant: number;
  /** Underground zones are unlit except for the player's light radius. */
  dark?: boolean;
  /** Visual floor-grid multiplier; it never changes movement or collision. */
  floorTileScale?: number;
}

type CampaignTerrainStyle = "trail" | "cavern" | "road" | "tomb";

/** Authored material groups for one floor atlas. */
interface CampaignTerrainProfile {
  /** Low-detail cells used for most of the ground. */
  ground: number[];
  /** Flatter, contrasting cells used for trails and clearings. */
  path: number[];
  /** Intermediate cells along the edge of a trail. */
  edge: number[];
  /** Rocks, roots, graves and plants placed in clusters off the walking line. */
  accents: number[];
  /** How the trail network is laid out for this kind of zone. */
  style: CampaignTerrainStyle;
}

interface CampaignTerrainPool extends CampaignTerrainProfile {
  /** The atlas cell requested by the area, kept as a load fallback. */
  base: number;
}

interface CampaignAct {
  act: number;
  name: string;
  region: string;
  levelLabel: string;
  map: string;
  mapAlpha: boolean;
  /** Authored area scene laid over the floor atlas (Tristram replaces it). */
  backdrop?: string;
  floorTiles: string;
  baseFloorVariant: number;
  enemies: EnemySpecies[];
  boss: EnemySpecies;
  /** Areas walked in order as the act clock advances (area tables). */
  areas: CampaignArea[];
  /** Pandemonium areas send every listed boss at once. */
  bosses?: EnemySpecies[];
  /** Level-83 event areas: their bosses hit far harder than campaign ones. */
  uber?: boolean;
}

