interface TristramWallInstance {
  x: number;
  y: number;
  w: number;
  h: number;
  sx: number;
  sy: number;
  order: number;
  depth?: number;
}

interface CampaignWorldDiamond {
  /** Centre of the walkable diamond, in backdrop pixels. */
  x: number;
  y: number;
  halfWidth: number;
  halfHeight: number;
}

interface TristramWallLayout {
  atlasWidth: number;
  atlasHeight: number;
  backdropWidth: number;
  backdropHeight: number;
  instances: TristramWallInstance[];
  /** The exported DS1 grid's walkable diamond, in backdrop pixels. */
  walkable?: CampaignWorldDiamond;
  /** Middle of a floor cell in the level's largest walkable region, in pixels. */
  spawn?: { x: number; y: number };
}

interface TristramWallDraw extends TristramWallInstance {
  dx: number;
  dy: number;
  dw: number;
  dh: number;
  depth: number;
  /** Alternate atlas for a backdrop-specific wall pass (Chaos Sanctuary). */
  atlas?: HTMLImageElement;
}

