function sanitizeEnemySpecies(value: unknown, kind: EnemyKind): EnemySpecies {
  return ENEMY_SPECIES.includes(value as EnemySpecies)
    ? value as EnemySpecies
    : ENEMY_SPECIES_BY_KIND[kind][0];
}

