  ownedSkills: string[] = [];
  /** Most recently cast skills, oldest first. Drives the HUD skill bar. */
  private recentSkillNames: string[] = [];
  /** Base ranks bought with skill points. Equipment bonuses are applied by the
   *  skillLevels accessor below, so they can never leak into a save or a level-up. */
  private readonly baseSkillLevels: Record<string, number> = {};
  private readonly skillLevelsProxy = new Proxy(this.baseSkillLevels, {
    get: (target, property, receiver) => {
      if (typeof property !== "string") return Reflect.get(target, property, receiver);
      const base = target[property] ?? 0;
      // A "+N to <skill>" staffmod also arms that skill outright, so a +1 Bone
      // Armor wand casts rank-1 Bone Armor with no point invested. Skill-tree and
      // class-wide bonuses only deepen skills the hero has already learned,
      // otherwise one "+1 to all skills" item would hand over the whole tree.
      const bonus = base > 0 ? this.equipmentSkillBonus(property) : this.equipmentNamedSkillBonus(property);
      if (!(property in target) && bonus === 0) return undefined;
      return base + bonus;
    },
  });

  get skillLevels(): Record<string, number> {
    return this.skillLevelsProxy;
  }

  set skillLevels(value: Record<string, number>) {
    for (const key of Object.keys(this.baseSkillLevels)) delete this.baseSkillLevels[key];
    for (const [name, rank] of Object.entries(value ?? {})) {
      if (Number.isFinite(rank)) this.baseSkillLevels[name] = rank;
    }
  }

