  private readonly itemDropAnimationArt = new Map<string, HTMLImageElement>();
  // Unique/set floor loot copies the bespoke hue of its inventory cel instead
  // of the base item's palette. The duotone is cached because sampling and
  // recolouring a cel is far too expensive to repeat for every draw frame.
  private readonly itemDropTintColors = new Map<string, [number, number, number] | null>();
  private readonly itemDropTintPending = new Set<string>();
  private readonly tintedItemDropArt = new Map<string, HTMLCanvasElement>();
  hoveredEnemy: Enemy | null = null;
  /** Name of the gold pile, potion or item under the cursor, drawn next to the pointer. */
  hoveredGroundPickup: { text: string; x: number; y: number; radius: number; source: GoldDrop | PotionDrop | ItemDrop } | null = null;
  /** D2's ALT: every potion, pile of gold and item on the floor shows its name. */
  altLootLabelsHeld = false;
  openChestCount = 0;
  floatingTexts: FloatingText[] = [];
  // Hit resolution is expensive when the arena is packed. A coarse spatial grid
  // narrows every area/segment check to nearby enemies, and damage from the
  // crowded paths (area bursts, auras, summons, orbiting traps) is coalesced into
  // a short batch so the same enemy is not re-scanned and re-texted for every source.
  private readonly enemyGridCellSize = 128;
  private enemyGridCells = new Map<number, Enemy[]>();
  private enemyQueryScratch: Enemy[] = [];
  private pendingDamage = new Map<Enemy, { damage: number; color: string; meleeDamage: number }>();
  private pendingDamageTimer = 0;
  private readonly damageBatchInterval = 0.5;
  // Monster sprites are tinted with a canvas colour filter. Running that filter
  // for every monster on every frame costs more than the rest of the draw pass,
  // so each species/direction/frame is tinted once into a small canvas and reused.
  private readonly tintedEnemyFrames = new Map<string, HTMLCanvasElement>();
  private tintedEnemyFramePixels = 0;
  private readonly tintedEnemyFramePixelBudget = 6000000;
  // Cached canvas metrics for projectArenaPoint: reading clientWidth while the
  // DOM is dirty forces a layout flush, so it is sampled once per frame instead.
  private projectionDpr = 1;
  private projectionCenterX = 400;
  private projectionCenterY = 250;
  private projectionWidth = 0;
  // Per-step caches for queries that used to rebuild lists on every call.
  private simulationStep = 0;
  private boneWallQueryStep = -1;
