  arenaH = 500;
  virtualJoystickVisible = false;
  joystickX = 0;
  joystickY = 0;
  joystickKnobX = 0;
  joystickKnobY = 0;
  private joystickPointerId: number | null = null;
  private joystickCenterX = 0;
  private joystickCenterY = 0;
  private readonly joystickRadius = 54;
