const CHAMPION_RING_COLORS: Record<ChampionType, string> = {
  champion: "#7f9dff",
  ghostly: "#b3ebff",
  fanatic: "#ff9a63",
  berserker: "#ff6a5c",
  possessed: "#c6a0ff",
};

/** The short trait blurb shown beneath a champion's hover health bar. */
const CHAMPION_TYPE_TRAITS: Record<ChampionType, string> = {
  champion: "Champion",
  ghostly: "Ghostly · ethereal · 50% slower · 20% cold attacks",
  fanatic: "Fanatic · +100% speed",
  berserker: "Berserker · massive damage",
  possessed: "Possessed · massive life",
};

/** Normal-difficulty champion bonuses. The game has no selectable difficulty yet. */
const CHAMPION_DAMAGE_MULTIPLIER = 1.9;
const CHAMPION_HEALTH_MULTIPLIER = 3;
const CHAMPION_SPEED_MULTIPLIER = 1.2;
const CHAMPION_LEVEL_BONUS = 2;
const GHOSTLY_PHYSICAL_RESIST = 80;
const GHOSTLY_COLD_ATTACK_CHANCE = 0.2;
const CHAMPION_STUN_CHANCE = 0.1;

function druidDirection(dx: number, dy: number): number {
  if (!Number.isFinite(dx) || !Number.isFinite(dy) || dx === 0 && dy === 0) return 0;
  const angle = Math.atan2(dy, dx);
  return (Math.round((angle + Math.PI) / (Math.PI / 4)) + 8) % 8;
}

/**
 * Atlas row for a wereform facing vector taken from the gameplay world plane.
 *
 * The wereform sheets are drawn in screen directions (row 0 faces left, row 4
 * faces right), but the hero's facing vector lives on the square world plane,
 * which the arena projects down 45 degrees with a 2:1 squash.  Selecting the row
 * straight from the world vector made walking left play the right-hand row, and
 * the wolf ran away from the player's input.
 */
export function wereformRow(facingX: number, facingY: number): number {
  return druidDirection(facingX - facingY, (facingX + facingY) * 0.5);
}

/**
 * How far to scale one sliced cel up so its body matches the walk rows. Attack
 * rows cut from a smaller export would otherwise make the wereform shrink for
 * the length of the swing. Rows already at (or above) the walk size are left
 * alone, and an empty cel never scales.
 */
export function wereformAttackRowScale(walkBodyHeight: number, rowBodyHeight: number): number {
  if (!(walkBodyHeight > 0) || !(rowBodyHeight > 0)) return 1;
  return Math.max(1, Math.min(WEREFORM_ATTACK_MAX_SCALE, walkBodyHeight / rowBodyHeight));
}

/** Opaque height and lowest pixel of one sliced cel, measured in cell pixels. */
function sliceCelBody(
  context: CanvasRenderingContext2D,
  width: number,
  height: number,
): { bodyHeight: number; bodyBottom: number } | undefined {
  const data = context.getImageData(0, 0, width, height).data;
  let top = -1;
  let bottom = -1;
  for (let y = 0; y < height; y += 1) {
    const rowStart = y * width * 4;
    let opaque = false;
    for (let x = 0; x < width; x += 1) {
      if (data[rowStart + x * 4 + 3] > 8) {
        opaque = true;
        break;
      }
    }
    if (!opaque) continue;
    if (top < 0) top = y;
    bottom = y;
  }
  if (top < 0) return undefined;
  return { bodyHeight: bottom - top + 1, bodyBottom: bottom + 1 };
}

function medianValue(values: number[]): number {
  if (values.length === 0) return 0;
  const sorted = [...values].sort((a, b) => a - b);
  return sorted[Math.floor(sorted.length / 2)];
}

function druidAttackFrame(columns: number, remainingSeconds: number, durationSeconds: number): number {
  const frameCount = Math.min(4, Math.max(2, Math.ceil(columns * 0.3)));
  const progress = 1 - Math.max(0, Math.min(1, remainingSeconds / durationSeconds));
  const frameOffset = Math.min(frameCount - 1, Math.floor(progress * frameCount));
  return Math.max(0, columns - frameCount + frameOffset);
}

/** The wereform attack row contains the whole attack, not just its follow-through. */
function druidFormAttackFrame(columns: number, remainingSeconds: number, durationSeconds: number): number {
  const progress = 1 - Math.max(0, Math.min(1, remainingSeconds / durationSeconds));
  return Math.min(columns - 1, Math.floor(progress * columns));
}

function druidAnimationFrame(
  summon: Enemy,
  animation: DruidAnimation,
  runTime: number,
  _moveX: number,
  _moveY: number,
  isCreeper: boolean,
  frameRate = 9,
  animateIdle = false,
): HTMLCanvasElement | undefined {
  const direction = druidDirection(summon.facingX ?? 1, summon.facingY ?? 0);
  const attackDuration = isCreeper ? 0.3 : 0.38;
  const frameIndex = summon.animationState === "attack"
    ? druidAttackFrame(animation.columns, summon.attackAnimationTime ?? attackDuration, attackDuration)
    : summon.animationState === "move"
      ? Math.floor(runTime * frameRate) % Math.max(2, Math.ceil((animation.walkColumns ?? animation.columns) * 0.7))
      : animateIdle
        ? Math.floor(runTime * frameRate) % animation.columns
        : Math.min(animation.columns - 1, Math.floor(animation.columns * 0.12));
  return animation.frames[direction]?.[frameIndex];
}
type EnemySpecies = "fallen" | "goatman" | "skeleton" | "sandRaider" | "sandMaggot" | "sandMaggotQueen" | "sandMaggotYoung" | "maggotEgg" | "scarab" | "spiderDemon" | "spikeFiend" | "leaper" | "blunderbore" | "fetish" | "boneFetish" | "fetishShaman" | "council" | "balrog" | "vileChild" | "vileMother" | "bloodLord" | "minotaur" | "nihlathak" | "painWorm" | "regurgitator" | "salamander" | "siegeBeast" | "deathMauler" | "wendigo" | "andariel" | "duriel" | "mephisto" | "diablo" | "baalsMinion" | "baal" | "wolf" | "grizzly" | "bloodGolem" | "fireGolem" | "ironGolem" | "oakSage" | "heartOfWolverine" | "spiritOfBarbs" | "skeletonWarrior" | "skeletalMageCold" | "skeletalMageFire" | "skeletalMageLightning" | "skeletalMagePoison" | "golem" | "hydra1" | "hydra2" | "hydra3";

type EnemyDamageType = "physical" | "fire" | "cold" | "lightning" | "poison" | "magic";

/** Base damage resistance per element, in percent. 100 or more is an immunity. */
type EnemyResistances = Partial<Record<EnemyDamageType, number>>;

const ENEMY_DAMAGE_TYPE_LABELS: Record<EnemyDamageType, string> = {
  physical: "Physical", fire: "Fire", cold: "Cold", lightning: "Lightning", poison: "Poison", magic: "Magic",
};

// Pandemonium enemies use Diablo II's familiar elemental identities: scarabs and
// fetishes punish lightning, the sandy beasts punish fire, and the act bosses
// each carry one signature immunity. Campaign monsters are left untouched.
const UBER_ENEMY_IMMUNITIES: Partial<Record<EnemySpecies, EnemyDamageType[]>> = {
  sandRaider: ["fire"], sandMaggot: ["poison"], scarab: ["lightning"], leaper: ["cold"], spikeFiend: ["lightning"],
  fallen: ["fire"], goatman: ["cold"], skeleton: ["cold"], fetish: ["lightning"], boneFetish: ["poison"],
  council: ["fire"], andariel: ["poison"], duriel: ["cold"], mephisto: ["lightning"], diablo: ["fire"], baal: ["cold"],
};

/** Diablo II's immunity threshold: at 100% resistance or more an element does nothing. */
const ENEMY_IMMUNE_RESIST = 100;
/** Resistance cannot amplify or reduce damage past these bounds. */
const ENEMY_MIN_RESIST = -100;
/**
 * Signature Pandemonium immunities sit above 100 so they are not cracked by a
 * token Conviction: only deep investment shaves them under the threshold.
 */
const UBER_IMMUNE_RESIST = 120;
/** Conviction: -30% at rank 1, -5% per rank after, capped at -150%. */
const CONVICTION_BASE_RESIST_REDUCTION = 30;
const CONVICTION_RESIST_REDUCTION_PER_RANK = 5;
const CONVICTION_MAX_RESIST_REDUCTION = 150;
/** Conviction only pierces these three; poison, magic and physical are untouched. */
const CONVICTION_DAMAGE_TYPES: readonly EnemyDamageType[] = ["fire", "cold", "lightning"];

/** An immunity list becomes the matching base resistances at the Uber value. */
function enemyResistancesFromImmunities(immunities?: EnemyDamageType[]): EnemyResistances | undefined {
  if (!immunities?.length) return undefined;
  const resistances: EnemyResistances = {};
  for (const damageType of immunities) resistances[damageType] = UBER_IMMUNE_RESIST;
  return resistances;
}

/**
 * One screen scale for every monster sprite. No species gets its own height
 * multiplier any more: each imported cel is drawn at this single scale, so the
 * source artwork's own relative sizes survive intact.
 */
const ENEMY_SOURCE_PIXEL_SCALE = 0.8;
/**
 * Drawn height of each species in source pixels; 90 here is one hero height
 * (90 * 0.8 = the hero's 72 world units), so 45 is a knee-high monster and 180
 * is twice the player. These are hand-tuned against how the original game
 * frames each monster beside the player: monstats2's pixHeight cannot be used
 * for this, it only sizes the hover/damage bar, which is why several entries
 * were off (the Balrog and Minions of Destruction stood barely taller than the
 * hero, the druid spirits twice his height).
 *
 * The spritesheets do not drive this. Every sheet was fitted into its own cell
 * at import time, so the runtime divides the cel by `sprite.contentHeight` and
 * rescales it to the value here - sheet pixels cancel out completely.
 *
 * The scale is measurable from the game files rather than guessed: the player
 * model's Diablo II cels are composed from the `chars/<class>` layers (head, torso,
 * legs, arms), and the tallest neutral cel of the Amazon measures 77 source
 * pixels from crown to feet. The table's unit is the hero's 90, so a monster
 * entry should read `tallest walk cel * (90 / 77)`. The entries below that were
 * left as old guesses - Death Maulers, spider demons, council members and the
 * Grizzly - sat well under the hero because their cel heights were never
 * converted; they now use that conversion (87/103/105/99 px -> 102/120/123/116).
 *
 * The next batch of guesses was converted the same way, from
 * tools/measure_walk_cels.py: goatman 73, blunderbore 138, sandRaider 123,
 * scarab 89, wendigo 109, salamander 100, painWorm 89, wolf 63, clay golem 64,
 * blood golem 73 and iron golem 95 source pixels -> 85/161/144/104/127/117/104/
 * 74/75/85/111.
 *
 * Four families still cannot use that rule: skeletons, skeletal mages, the
 * minotaur/Blood Lord (L3) and Baal's minions (43) are layered COF composites,
 * and a single walk DCC there is one body part (SK's 1hs arm layer measures 25,
 * L3's body 36, 43's body 49). Their height has to be measured across every COF
 * layer of a frame instead, so they stay on their current values until then.
 *
 * Two entries deviate from the art's own proportions on purpose. The minotaur
 * (L3, the Blood Lord composite) keeps 122 because its 128px atlas preserves
 * the source frame boxes. The leaper is the opposite: its 96 was the height of
 * the whole hop silhouette, and every cel is scaled by content height, so 96
 * made it stand both taller and wider than the hero; 64 sits just under him.
 */
const ENEMY_D2_PIX_HEIGHTS: Partial<Record<EnemySpecies, number>> = {
  fallen: 64, goatman: 85, skeleton: 80, skeletonWarrior: 80,
  skeletalMageCold: 80, skeletalMageFire: 80, skeletalMageLightning: 80, skeletalMagePoison: 80,
  golem: 75, sandRaider: 144, sandMaggot: 48, sandMaggotYoung: 32, sandMaggotQueen: 48, maggotEgg: 32,
  scarab: 104, spiderDemon: 120, spikeFiend: 48, leaper: 64, blunderbore: 161,
  fetish: 48, boneFetish: 48, fetishShaman: 64, council: 123,
  // Act IV/V heavy hitters: the Balrog is the tallest non-boss demon in the
  // game (its 224x152 atlas cell is the source frame box), Minions of
  // Destruction tower over the hero, and the Blood Lord is the same L3 art
  // the minotaur below is built from - it was reading at 64px, under the
  // hero, while the identical creature next to it read at 122.
  balrog: 152, baalsMinion: 136, bloodLord: 118,
  vileChild: 48, vileMother: 96, minotaur: 122, nihlathak: 80,
  painWorm: 104, regurgitator: 112, salamander: 117, siegeBeast: 128, deathMauler: 102, wendigo: 127,
  andariel: 96, duriel: 112, mephisto: 112, diablo: 112, baal: 112,
  wolf: 74, grizzly: 116, bloodGolem: 85, fireGolem: 96, ironGolem: 111,
  // Waist-high floating spirits, not the 88px wolf/bear stand-ins they were.
  oakSage: 48, heartOfWolverine: 48, spiritOfBarbs: 48,
  hydra1: 90, hydra2: 90, hydra3: 90,
};

export function enemyD2PixelHeight(species: EnemySpecies): number {
  return ENEMY_D2_PIX_HEIGHTS[species] ?? 96;
}

/** World-unit height the hero's 3D model is normalized to before arena scaling. */
const PLAYER_MODEL_HEIGHT = 72;
/**
 * Boss heights in hero-heights. Diablo, Duriel and Baal tower over the player;
 * Mephisto and Andariel are shorter but still clearly boss-sized, and the two
 * super-unique mini bosses stay close to human scale.
 */
const BOSS_HERO_HEIGHT_RATIOS: Partial<Record<EnemySpecies, number>> = {
  andariel: 2, duriel: 2.5, mephisto: 2.3, diablo: 2.6, baal: 2.5,
  nihlathak: 1.3, sandMaggotQueen: 1.4,
};
const DEFAULT_BOSS_HERO_HEIGHT_RATIO = 2.2;

/**
 * Fresh block atlases: [walk frames per direction, attack frames per direction],
 * or [idle, walk, attack] for the mage sheets that carry a neutral clip.
 */
const ENEMY_ROW_BLOCK_FRAMES: Partial<Record<EnemySpecies, [number, number] | [number, number, number]>> = {
  // D2R's normal SK walk cycle is eight frames; its melee attack is sixteen.
  skeleton: [8, 16], skeletonWarrior: [8, 16],
  // SK's neutral clip is eight frames; its glowing hands keep moving in idle.
  skeletalMageCold: [8, 8, 16], skeletalMageFire: [8, 8, 16],
  skeletalMageLightning: [8, 8, 16], skeletalMagePoison: [8, 8, 16],
  balrog: [8, 16], bloodLord: [8, 16], spiderDemon: [12, 11],
  // SI's quill volley is the ranged a2 clip: nine walk cels and thirteen
  // throw cels per facing.
  spikeFiend: [9, 13], fetishShaman: [14, 17],
  // OX's original DCCs hold eight walk cels and nine strike cels per
  // direction. The old runtime looped eighteen and twelve, sampling the empty
  // columns the importer left behind and making the beast blink out.
  siegeBeast: [8, 9],
  duriel: [16, 10],
  wolf: [8, 13], grizzly: [12, 13], bloodGolem: [8, 16], fireGolem: [8, 17], ironGolem: [8, 16],
  // Hydra's neutral and attack clips are both twelve cels per facing.
  hydra1: [12, 12, 12], hydra2: [12, 12, 12], hydra3: [12, 12, 12],
};

/** Four-row spirit atlases: one slow drift cycle, one row per direction. */
/**
 * The druid spirits were imported as four rows of a seven-frame walk and nothing
 * else. `enemySpriteFrame` loops that whole cycle at the rate below instead of
 * the old six-of-seven modulo that stuttered through the roll.
 */
const ENEMY_WALK_ONLY_FRAMES: Partial<Record<EnemySpecies, number>> = {
  oakSage: 7, heartOfWolverine: 7, spiritOfBarbs: 7,
};
const ENEMY_WALK_ONLY_RATE = 11;

/**
 * Species whose atlas carries a real neutral clip in its third block: walk in
 * rows 0-7, attack in rows 8-15 and the `nu` idle animation in rows 16-23.
 * tools/add_enemy_idle_blocks.py appends that block, and the value here is how
 * many frames of it hold art. Standing still plays it, so a monster waiting for
 * its next order breathes instead of freezing on a single walk cel.
 */
const ENEMY_IDLE_TAIL_FRAMES: Partial<Record<EnemySpecies, number>> = {
  goatman: 10, skeletonWarrior: 8, golem: 4, sandRaider: 15, sandMaggotYoung: 8,
  spiderDemon: 12, spikeFiend: 8, scarab: 8, leaper: 11, blunderbore: 8,
  fetishShaman: 12, balrog: 8, bloodLord: 8, minotaur: 8, nihlathak: 8,
  painWorm: 5, regurgitator: 9, salamander: 8, siegeBeast: 10, vileChild: 4,
  vileMother: 13,
  // Druid pets, the three golems and Duriel: their `nu` clips, appended by
  // tools/add_enemy_idle_blocks.py below the walk and attack bands.
  wolf: 13, grizzly: 12, bloodGolem: 4, fireGolem: 8, ironGolem: 4, duriel: 12,
};
/** The same species as a set, for the row maths that must agree with the block. */
const ENEMY_IDLE_TAIL_SPECIES = new Set<EnemySpecies>(Object.keys(ENEMY_IDLE_TAIL_FRAMES) as EnemySpecies[]);
/** Frames per second of a neutral idle loop; D2's `nu` clips are slow breaths. */
const ENEMY_IDLE_RATE = 6;

function enemySpriteFrame(enemy: Enemy, columns: number, runTime: number): number {
  if (columns <= 1) return 0;
  if ((enemy.freezeRemaining ?? 0) > 0) return 0;
  const state = enemy.animationState ?? "idle";
  const phaseOffset = Math.abs(Math.floor(enemy.x * 0.09 + enemy.y * 0.05)) % columns;
  const idleTailFrames = ENEMY_IDLE_TAIL_FRAMES[enemy.species] ?? 0;
  if (state === "idle" && idleTailFrames > 0) {
    // The appended neutral block is the only idle art these sheets have, so it
    // has to win over every species branch below that would hold frame 0.
    return Math.floor(runTime * ENEMY_IDLE_RATE + phaseOffset) % idleTailFrames;
  }
  if (enemy.species === "sandMaggot" || enemy.species === "sandMaggotQueen") {
    // Four stacked clips in maggot.png: walk (8), bite (18), poison spit/egg
    // lay (10), burrow (12). A missing block means idle or the bite band.
    const block = enemy.spriteBlock ?? (state === "attack" ? 1 : 0);
    const blockFrames = [8, 18, 10, 12][block] ?? 8;
    if (block === 0) {
      return state === "move" ? Math.floor(runTime * 12 + phaseOffset) % 8 : 0;
    }
    const duration = enemy.attackDuration ?? (block === 1 ? 0.38 : 0.8);
    const progress = 1 - Math.max(0, Math.min(1, (enemy.attackAnimationTime ?? duration) / duration));
    return Math.min(blockFrames - 1, Math.floor(progress * blockFrames));
  }
  // Fresh block atlases loop each band over its own length: the walk cycle in
  // rows 0-7 and the attack in rows 8-15, plus a neutral idle band above them for
  // the mage sheets, imported at the frame counts below.
  const rowBlockFrames = ENEMY_ROW_BLOCK_FRAMES[enemy.species];
  if (rowBlockFrames) {
    // A three-entry table carries the neutral clip first; holding frame 0 while
    // standing still froze the mage's glowing hands.
    const idleFrames = rowBlockFrames.length === 3 ? rowBlockFrames[0] : 0;
    const walkFrames = rowBlockFrames.length === 3 ? rowBlockFrames[1] : rowBlockFrames[0];
    const attackFrames = rowBlockFrames.length === 3 ? rowBlockFrames[2] : rowBlockFrames[1];
    if (state === "attack") {
      const duration = enemy.kind === "boss" ? 0.55 : 0.38;
      const progress = 1 - Math.max(0, Math.min(1, (enemy.attackAnimationTime ?? duration) / duration));
      return Math.min(attackFrames - 1, Math.floor(progress * attackFrames));
    }
    if (state === "move") return Math.floor(runTime * 10 + phaseOffset) % walkFrames;
    if (idleFrames > 0) return Math.floor(runTime * 7 + phaseOffset) % idleFrames;
    return 0;
  }
  const walkOnlyFrames = ENEMY_WALK_ONLY_FRAMES[enemy.species];
  if (walkOnlyFrames) return Math.floor(runTime * ENEMY_WALK_ONLY_RATE + phaseOffset) % walkOnlyFrames;
  if (enemy.species === "scarab") {
    // Rows 0-7 are the walk cycle, rows 8-15 the spit attack. The walk band has
    // 14 frames; the remaining columns repeat its last pose.
    const walkFrames = 14;
    if (state === "attack") {
      const duration = enemy.kind === "boss" ? 0.55 : 0.38;
      const progress = 1 - Math.max(0, Math.min(1, (enemy.attackAnimationTime ?? duration) / duration));
      return Math.min(columns - 1, Math.floor(progress * columns));
    }
    if (state === "move") return Math.floor(runTime * 11 + phaseOffset) % walkFrames;
  }
  if (enemy.species === "sandRaider") {
    // Rows 0-7 walk/scuttle, rows 8-15 the strike. Both bands were imported at
    // their own frame counts, so each band loops over its own length.
    const walkFrames = 21;
    const attackFrames = 15;
    if (state === "attack") {
      const duration = enemy.kind === "boss" ? 0.55 : 0.38;
      const progress = 1 - Math.max(0, Math.min(1, (enemy.attackAnimationTime ?? duration) / duration));
      return Math.min(attackFrames - 1, Math.floor(progress * attackFrames));
    }
    if (state === "move") return Math.floor(runTime * 24 + phaseOffset) % walkFrames;
  }
  if (enemy.species === "sandMaggotYoung") {
    // Rows 0-7 hold SB's eight-frame crawl, rows 8-15 the eighteen-frame bite.
    if (state === "attack") {
      const duration = enemy.kind === "boss" ? 0.55 : 0.38;
      const progress = 1 - Math.max(0, Math.min(1, (enemy.attackAnimationTime ?? duration) / duration));
      return Math.min(17, Math.floor(progress * 18));
    }
    if (state === "move") return Math.floor(runTime * 14 + phaseOffset) % 8;
  }
  if (enemy.species === "salamander") {
    // Rows 0-7 are the sixteen-frame crawl, rows 8-15 the fourteen-frame rear-up.
    if (state === "attack") {
      const duration = enemy.kind === "boss" ? 0.55 : 0.38;
      const progress = 1 - Math.max(0, Math.min(1, (enemy.attackAnimationTime ?? duration) / duration));
      return Math.min(13, Math.floor(progress * 14));
    }
    if (state === "move") return Math.floor(runTime * 8 + phaseOffset) % 16;
  }
  if (enemy.species === "regurgitator") {
    // Rows 0-7 are the ten-frame sway, rows 8-15 the ten-frame lunge.
    if (state === "attack") {
      const duration = enemy.kind === "boss" ? 0.55 : 0.38;
      const progress = 1 - Math.max(0, Math.min(1, (enemy.attackAnimationTime ?? duration) / duration));
      return Math.min(9, Math.floor(progress * 10));
    }
    if (state === "move") return Math.floor(runTime * 8 + phaseOffset) % 10;
  }
  if (enemy.species === "painWorm") {
    // Rows 0-7 are the nine-frame crawl, rows 8-15 the eight-frame spit.
    if (state === "attack") {
      const duration = enemy.kind === "boss" ? 0.55 : 0.38;
      const progress = 1 - Math.max(0, Math.min(1, (enemy.attackAnimationTime ?? duration) / duration));
      return Math.min(7, Math.floor(progress * 8));
    }
    if (state === "move") return Math.floor(runTime * 11 + phaseOffset) % 9;
  }
  if (enemy.species === "nihlathak") {
    // Rows 0-7 are the eight-step walk, rows 8-15 the fourteen-frame strike.
    if (state === "attack") {
      const duration = enemy.kind === "boss" ? 0.55 : 0.38;
      const progress = 1 - Math.max(0, Math.min(1, (enemy.attackAnimationTime ?? duration) / duration));
      return Math.min(13, Math.floor(progress * 14));
    }
    if (state === "move") return Math.floor(runTime * 9 + phaseOffset) % 8;
  }
  if (enemy.species === "minotaur") {
    // Rows 0-7 are the eight-step walk, rows 8-15 the two-handed axe swing.
    if (state === "attack") {
      const duration = enemy.kind === "boss" ? 0.55 : 0.38;
      const progress = 1 - Math.max(0, Math.min(1, (enemy.attackAnimationTime ?? duration) / duration));
      return Math.min(15, Math.floor(progress * 16));
    }
    if (state === "move") return Math.floor(runTime * 9 + phaseOffset) % 8;
  }
  if (enemy.species === "leaper") {
    // Rows 0-7 are the nine-frame hop, rows 8-15 the twenty-frame lunge.
    if (state === "attack") {
      const duration = LEAPER_ATTACK_ANIMATION_SECONDS;
      const progress = 1 - Math.max(0, Math.min(1, (enemy.attackAnimationTime ?? duration) / duration));
      return Math.min(19, Math.floor(progress * 20));
    }
    if (state === "move") return Math.floor(runTime * 14 + phaseOffset) % 9;
  }
  if (enemy.species === "blunderbore") {
    // Rows 0-7 are the eight-step walk, rows 8-15 the club swing. The imported
    // A1 sequence spends its last seven frames in a deep post-swing crouch and
    // its final cel is empty, which made the brute collapse to two-thirds height
    // and blink out at the end of every attack. Play the wind-up and strike up
    // to frame 8, then let the standing idle pose take over.
    if (state === "attack") {
      const duration = enemy.kind === "boss" ? 0.55 : 0.38;
      const progress = 1 - Math.max(0, Math.min(1, (enemy.attackAnimationTime ?? duration) / duration));
      const attackFrames = 9;
      return Math.min(attackFrames - 1, Math.floor(progress * attackFrames));
    }
    if (state === "move") return Math.floor(runTime * 10 + phaseOffset) % 8;
  }
  if (enemy.species === "mephisto") {
    // MP's DC6 COFs hold thirteen idle frames, thirteen walk frames and
    // eighteen attack frames. The old sheet repeated one neutral pose in the
    // walk band, which made the boss glide across the arena without stepping.
    if (state === "move") return Math.floor(runTime * 9 + phaseOffset) % 13;
    if (state === "attack") {
      const duration = enemy.kind === "boss" ? 0.55 : 0.38;
      const progress = 1 - Math.max(0, Math.min(1, (enemy.attackAnimationTime ?? duration) / duration));
      return Math.min(17, Math.floor(progress * 18));
    }
    return Math.floor(runTime * 4 + phaseOffset) % 13;
  }
  if (enemy.species === "council") {
    // HP's COFs hold seven idle frames, eleven walk frames and ten attack
    // frames. The sheet repeats those clips across the rest of its twenty
    // columns, so these counts must stay inside the real clip.
    if (state === "move") return Math.floor(runTime * 9 + phaseOffset) % 11;
    if (state === "attack") {
      const duration = enemy.kind === "boss" ? 0.55 : 0.38;
      const progress = 1 - Math.max(0, Math.min(1, (enemy.attackAnimationTime ?? duration) / duration));
      return Math.min(9, Math.floor(progress * 10));
    }
    return Math.floor(runTime * 4 + phaseOffset) % 7;
  }
  if (enemy.species === "fetish" || enemy.species === "boneFetish") {
    // FE/FK neutral has twelve frames, walk six and attack twelve. The old
    // twelve-column walk loop spent half the cycle on empty cels, which is why
    // both fetishes vanished while moving.
    if (state === "move") return Math.floor(runTime * 9 + phaseOffset) % 6;
    if (state === "attack") {
      const duration = enemy.kind === "boss" ? 0.55 : 0.38;
      const progress = 1 - Math.max(0, Math.min(1, (enemy.attackAnimationTime ?? duration) / duration));
      return Math.min(11, Math.floor(progress * 12));
    }
    return Math.floor(runTime * 5 + phaseOffset) % 12;  }
  if (enemy.species === "baalsMinion" || enemy.species === "baal") {
    const frameCounts = enemy.species === "baal" ? { idle: 12, move: 12, attack: 14 } : { idle: 12, move: 12, attack: 12 };
    if (state === "attack") {
      const duration = enemy.kind === "boss" ? 0.55 : 0.38;
      const progress = 1 - Math.max(0, Math.min(1, (enemy.attackAnimationTime ?? duration) / duration));
      return Math.min(frameCounts.attack - 1, Math.floor(progress * frameCounts.attack));
    }
    if (state === "move") return Math.floor(runTime * 9 + phaseOffset) % frameCounts.move;
    return Math.floor(runTime * 3 + phaseOffset) % frameCounts.idle;
  }
  if (enemy.species === "diablo" && columns === 16) {
    if (state === "attack") {
      const progress = 1 - Math.max(0, Math.min(1, (enemy.attackAnimationTime ?? 0.55) / 0.55));
      return Math.min(15, Math.floor(progress * 16));
    }
    if (state === "move") return Math.floor(runTime * 9 + phaseOffset) % 6;
    return Math.floor(runTime * 4 + phaseOffset) % 16;
  }
  if (enemy.species === "goatman") {
    if (state === "attack") {
      const duration = enemy.kind === "boss" ? 0.55 : 0.38;
      const progress = 1 - Math.max(0, Math.min(1, (enemy.attackAnimationTime ?? duration) / duration));
      return Math.min(columns - 1, Math.floor(progress * columns));
    }
    // GM walk DCCs hold eight frames, but the atlas reserves fourteen columns
    // for the attack. Looping the full width made the goatman blink out for the
    // six empty walk columns.
    if (state === "move") return Math.floor(runTime * 10 + phaseOffset) % 8;
  }
  if (state === "attack") {
    const attackProgress = 1 - (enemy.attackAnimationTime ?? 0) / (enemy.kind === "boss" ? 0.55 : 0.38);
    // A brief, readable wind-up/strike/recovery cadence replaces the old
    // endless walk cycle while the enemy attacks.
    const attackStep = Math.min(2, Math.floor(Math.max(0, Math.min(0.999, attackProgress)) * 3));
    return (Math.floor(columns * (0.45 + attackStep * 0.12)) + phaseOffset) % columns;
  }
  if (state === "idle" && enemy.spriteFrame >= 0 && enemy.spriteFrame < columns) {
    return enemy.spriteFrame;
  }
  if (state === "move") {
    const walkFrames = Math.max(2, Math.ceil(columns * 0.72));
    return (Math.floor(runTime * 7) + phaseOffset) % walkFrames;
  }
  // Hold a stable neutral frame when standing still instead of cycling through
  // locomotion sprites while the monster is waiting for its next attack.
  return Math.min(columns - 1, Math.floor(columns * 0.12));
}

/** Every imported atlas stacks its animation blocks eight direction rows deep. */
const ENEMY_BLOCK_ROWS = 8;

/**
 * The imported atlases stack a few blocks of eight directions on top of each
 * other (idle, walk, attack). Species differ in how many blocks they hold and in
 * their order, so every draw path that renders a monster cel asks this helper for
 * the row instead of open coding the table again.
 */
export function enemySpriteDirectionRow(
  species: EnemySpecies,
  state: Enemy["animationState"] | undefined,
  rows: number,
  directionRow: number,
  spriteBlock?: number,
): number {
  if (spriteBlock !== undefined && rows >= 32) return (spriteBlock * ENEMY_BLOCK_ROWS + directionRow) % rows;
  // Walk, attack and idle stacked in that order: the idle clip is the appended
  // third block, so standing still reads the block after the attack one.
  if (ENEMY_IDLE_TAIL_SPECIES.has(species)) {
    const offset = state === "attack" ? ENEMY_BLOCK_ROWS : state === "idle" ? ENEMY_BLOCK_ROWS * 2 : 0;
    return (offset + directionRow) % rows;
  }
  const block = (): number =>
    (state === "attack" ? ENEMY_BLOCK_ROWS * 2 : state === "move" ? ENEMY_BLOCK_ROWS : 0) + directionRow;
  // The mage sheets hold idle, walk and attack blocks in that order.
  if (ENEMY_MAGE_SPECIES.has(species)) return block();
  if (species === "fetish" || species === "boneFetish") return block();
  if (species === "council" || species === "mephisto") return block();
  if (species === "diablo" && rows === 24) return block();
  if (species === "baalsMinion" || species === "baal") return block();
  // Walk rows above attack rows, with no idle block: walking shows the walk band
  // and attacking the band below it, both in the same direction.
  if (ENEMY_WALK_ATTACK_BLOCK_SPECIES.has(species)) {
    return directionRow + (state === "attack" ? ENEMY_BLOCK_ROWS : 0);
  }
  return directionRow % rows;
}

// Sixteen-row atlases hold eight walk rows above eight attack rows. The old
// four-row band offset made the second half of every walk cycle come from the
// attack block, so all of these species turned the wrong way while moving.
const ENEMY_MAGE_SPECIES = new Set<EnemySpecies>([
  "skeletalMageCold", "skeletalMageFire", "skeletalMageLightning", "skeletalMagePoison",
]);

/**
 * Sheets that stack their walk rows directly above their attack rows and carry no
 * idle block. Every other walk-over-attack sheet also has an appended idle tail,
 * which `ENEMY_IDLE_TAIL_SPECIES` (built from `ENEMY_IDLE_TAIL_FRAMES`) handles
 * first, so listing those here again would be dead. `enemySpriteRow` reads the
 * same set for the direction count, so the two stay in step.
 */
const ENEMY_WALK_ATTACK_BLOCK_SPECIES = new Set<EnemySpecies>([
  "skeleton",
  // The maggot sheets stack four clips of eight direction rows and address them
  // with `spriteBlock`; only their single-row direction read lands here.
  "sandMaggot", "sandMaggotQueen",
]);

// Imported DCC direction rows run SW, NW, NE, SE, S, W, N, E, while the
// generic sheet mapping below emits W, NW, N, NE, E, SE, S, SW.
const DCC_EIGHT_DIRECTION_ROWS = [5, 1, 6, 2, 7, 3, 4, 0] as const;
// Every sheet below was imported with its source DCC rows intact (verified by
// matching each walk row against the source directions), so all of them need
// the remap. This includes Baal/Diablo/Andariel and the summon atlases; leaving
// them out made south-facing movement display the north row.
const DCC_EIGHT_DIRECTION_SPECIES = new Set<EnemySpecies>([
  "skeleton", "skeletonWarrior", "skeletalMageCold", "skeletalMageFire", "skeletalMageLightning", "skeletalMagePoison",
  "goatman", "regurgitator", "siegeBeast", "minotaur", "baalsMinion", "leaper",
  "scarab", "sandRaider", "sandMaggot", "sandMaggotQueen", "sandMaggotYoung", "spiderDemon", "spikeFiend", "blunderbore",
  "fetish", "boneFetish", "fetishShaman", "council", "balrog", "vileChild", "vileMother", "bloodLord", "nihlathak",
  // The Pain Worm page preserves its source DCC rows too; without the remap
  // moving left played the south-west row and read as walking backwards.
  "painWorm", "salamander", "deathMauler", "wendigo", "andariel", "duriel", "diablo", "baal", "mephisto",
  "wolf", "grizzly", "bloodGolem", "fireGolem", "ironGolem",
]);

export function enemySpriteRow(species: EnemySpecies, dx: number, dy: number): number {
  const layoutRows = ENEMY_SPRITE_LAYOUTS[species].rows;
  // Three stacked blocks (idle/walk/attack in either order) or the two-block walk
  // and attack sheets; the block sets above are the only place those are listed.
  const directions = ENEMY_IDLE_TAIL_SPECIES.has(species) || ENEMY_MAGE_SPECIES.has(species) ? layoutRows / 3
    : ENEMY_WALK_ATTACK_BLOCK_SPECIES.has(species) ? layoutRows / 2
    : species === "fetish" || species === "boneFetish" || species === "council" || species === "mephisto" || (species === "diablo" && layoutRows === 24) || species === "baalsMinion" || species === "baal" ? layoutRows / 3 : layoutRows;
  if (directions === 8) {
    const angle = Math.atan2(dy, dx);
    const row = (Math.round((angle + Math.PI) / (Math.PI / 4)) + 8) % 8;
    // These atlases keep the DCC row order, so without this remap their
    // south-facing walk used the north row and they appeared to walk backwards.
    return DCC_EIGHT_DIRECTION_SPECIES.has(species) ? DCC_EIGHT_DIRECTION_ROWS[row] : row;
  }
  return 0;
}

