interface D2InventoryItem {
  id: string;
  name: string;
  baseName?: string;
  rarity: "normal" | "magic" | "rare" | "unique" | "set";
  slot: "weapon" | "armor" | "charm" | "belt";
  equipmentType?: EquipmentType;
  restrictedClass?: D2ClassId;
  /** Explicit fallback for legacy/custom items; known D2 bases resolve in d2-item-footprints.ts. */
  width?: number;
  height?: number;
  beltQuality?: BeltQuality;
  requiredLevel?: number;
  setName?: string;
  sockets?: number;
  /** Set once this base's sockets spell a completed runeword. */
  runeword?: string;
  /** Inventory cel for socketables that roll art of their own (jewels). */
  art?: string;
  /** Contents of the filled sockets, in the order they were set. */
  socketed?: D2SocketedContent[];
  procs?: D2ItemProc[];
  desc: string;
  stats?: D2ItemStats;
  affixes?: string[];
}

type InventoryCellItem = D2InventoryItem | null;


